  compile (lines) {
    const text = lines
      .map(line =&gt; line.trim())
      .filter(line =&gt; (line.length &gt; 0) && !line.startsWith('//'))
      .join('\n')
    return JSON.parse(text)
  }

  run () {
    this.env = {}
    this.runAll(this.program)
